import"./hoisted.BrKH_MOv.js";const t=document.getElementById("contact-form"),e=document.getElementById("form-feedback");t&&e&&t.addEventListener("submit",async o=>{o.preventDefault(),e.textContent="Sending your message...",e.className="form-feedback form-feedback--info";const n=new FormData(t),s=Object.fromEntries(n.entries());try{if((await fetch("/api/contact",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(s)})).ok)e.textContent="Thank you! Your message has been sent successfully. We will get back to you soon.",e.className="form-feedback form-feedback--success",t.reset();else throw new Error("Failed to send message.")}catch{e.textContent="Oops! Something went wrong. Please try again or call us directly.",e.className="form-feedback form-feedback--error"}});
